import{_ as t,o as n,c as a,ao as o}from"./chunks/framework.D7TN4pt9.js";const g=JSON.parse('{"title":"A second frontend","description":"","frontmatter":{},"headers":[],"relativePath":"guide/second-frontend.md","filePath":"guide/second-frontend.md","lastUpdated":null}'),s={name:"guide/second-frontend.md"};function d(r,e,i,h,c,l){return n(),a("div",null,[...e[0]||(e[0]=[o('<h1 id="A-second-frontend" tabindex="-1">A second frontend <a class="header-anchor" href="#A-second-frontend" aria-label="Permalink to &quot;A second frontend {#A-second-frontend}&quot;">​</a></h1><p>The backend owns the project state — sessions, kernels, file watching — and the frontend renders what it is sent. So a desktop and a laptop can attach to the <strong>same backend at once</strong> and see the same sessions, the same work-state colors and the same REPLs.</p><h2 id="Add-one" tabindex="-1">Add one <a class="header-anchor" href="#Add-one" aria-label="Permalink to &quot;Add one {#Add-one}&quot;">​</a></h2><p>The hub&#39;s <code>~/.config/sot/hosts.toml</code> must list the second machine (<code>[host.&lt;box&gt;]</code> with <code>frontend = true</code>) before its install, or the install ends in a <code>FAIL: enroll:</code> line that names the command to run on the hub. Then install the frontend role on that machine against the same backend SSH alias, with <code>install.sh --backend &lt;ssh-alias&gt;</code>, or on Windows with the release&#39;s <code>scripts\\install.ps1 -Hub &lt;hub-ssh-alias&gt;</code>. The commands are in <a href="./../start/remote">Going remote</a> and <a href="./../start/install">Install</a>. Launch it with <code>sot-launch</code>; it spawns its own <code>ssh</code> child and connects as one more client of the daemon.</p><h2 id="What-is-shared-and-what-is-not" tabindex="-1">What is shared and what is not <a class="header-anchor" href="#What-is-shared-and-what-is-not" aria-label="Permalink to &quot;What is shared and what is not {#What-is-shared-and-what-is-not}&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:right;">Shared (lives on the backend)</th><th style="text-align:right;">Per frontend</th></tr></thead><tbody><tr><td style="text-align:right;">sessions and their agents</td><td style="text-align:right;">window layout and which pane has focus</td></tr><tr><td style="text-align:right;">each workspace&#39;s Julia kernel and REPL</td><td style="text-align:right;">the active session and cursor positions</td></tr><tr><td style="text-align:right;">work-state colors and comm messages</td><td style="text-align:right;">the Terminal drawer (a shell on <em>that</em> machine)</td></tr><tr><td style="text-align:right;">files and previews</td><td style="text-align:right;"><code>settings.toml</code> (layout preset, GPU preference)</td></tr></tbody></table><p>The agents run under the backend&#39;s own supervisors, not under any frontend, so closing a frontend on another computer than the backend ends nothing. Closing the last window on the computer that runs the backend ends its sessions, including any that the other frontend was viewing; see <a href="./../start/running">What keeps running</a>.</p><h2 id="browser-window" tabindex="-1">Where a session&#39;s output lands <a class="header-anchor" href="#browser-window" aria-label="Permalink to &quot;Where a session&#39;s output lands {#browser-window}&quot;">​</a></h2><p>With two windows attached, a file an agent shows (<code>sot-fe preview</code>, <code>show-result</code>) reaches the preview pane and the badge of <strong>every</strong> window. A browser an agent opens (a docs site, a URL, a <code>wglshow</code> figure) opens on <strong>one</strong> computer: the window you used last, however long ago; with none used yet, the one that connected last. A window counts as used from its second key press, click or wheel step within five minutes, and a switch between windows is noticed within about six seconds. Name a window with <code>--fe &lt;host&gt;</code> to override this. A window that is reconnecting at that moment is not chosen, and a browser open cannot wait for it.</p><h2 id="Many-machines,-one-workspace" tabindex="-1">Many machines, one workspace <a class="header-anchor" href="#Many-machines,-one-workspace" aria-label="Permalink to &quot;Many machines, one workspace {#Many-machines,-one-workspace}&quot;">​</a></h2><p>To make a server reachable from every frontend in a fleet — not only the one you installed it from — enroll it on the hub: see <a href="./enrolling">Enrolling a host</a>.</p>',11)])])}const u=t(s,[["render",d]]);export{g as __pageData,u as default};
